/* R123H_MODEL_HEIGHT_BEGIN: the actual model canvas fills the stage's free space.
   The original setup remains its desktop peer and its mobile alternate. */
#smWorkspace[open] {
  display: grid;
  grid-template-columns: minmax(0, 1fr) var(--r123h-dialog-dock);
  grid-template-rows: var(--r123h-dialog-header) minmax(0, 1fr);
}
#smWorkspace > .sm-header {
  grid-column: 1 / -1;
  grid-row: 1;
  height: var(--r123h-dialog-header);
  min-height: var(--r123h-dialog-header);
  box-sizing: border-box;
}
#smWorkspace > #smMain,
#smWorkspace > #smLibraryPanel {
  grid-column: 1;
  grid-row: 2;
  min-width: 0;
  min-height: 0;
  height: 100%;
}
#smWorkspace > #smMain { margin: 0; padding: 0; border: 0; gap: 0; }
#smWorkspace .sm-stage {
  min-width: 0;
  min-height: 0;
  overflow: hidden;
  margin: 0;
  padding: 0;
  border: 0;
}
#smWorkspace .sm-canvas-wrap {
  flex: 1 1 auto;
  min-width: 0;
  min-height: 0;
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  border: 0;
}
#smWorkspace .sm-canvas-wrap > canvas { display: block; width: 100%; height: 100%; }
#smWorkspace .sm-setup { min-width: 0; }
/* R123H_MODEL_HEIGHT_END */
